class AVLNode:
    def __init__(self, k): self.k=k; self.l=self.r=None; self.h=1

def _h(n): return n.h if n else 0
def _bal(n): return _h(n.l)-_h(n.r) if n else 0
def _upd(n): n.h=1+max(_h(n.l),_h(n.r))

def _rl(n):
    r=n.r; n.r=r.l; r.l=n; _upd(n); _upd(r); return r
def _rr(n):
    l=n.l; n.l=l.r; l.r=n; _upd(n); _upd(l); return l

def insert(n, k):
    if not n: return AVLNode(k)
    if k<n.k: n.l=insert(n.l,k)
    elif k>n.k: n.r=insert(n.r,k)
    else: return n
    _upd(n); b=_bal(n)
    if b>1 and k<n.l.k: return _rr(n)
    if b<-1 and k>n.r.k: return _rl(n)
    if b>1 and k>n.l.k: n.l=_rl(n.l); return _rr(n)
    if b<-1 and k<n.r.k: n.r=_rr(n.r); return _rl(n)
    return n
```
O(log n) per insert via height-balanced rotations.

