class SegTree:
    def __init__(self, arr):
        self.n=len(arr); self.t=[0]*(4*self.n)
        self._build(arr,1,0,self.n-1)
    def _build(self,a,v,l,r):
        if l==r: self.t[v]=a[l]; return
        m=(l+r)//2
        self._build(a,2*v,l,m); self._build(a,2*v+1,m+1,r)
        self.t[v]=self.t[2*v]+self.t[2*v+1]
    def update(self,i,x): self._u(1,0,self.n-1,i,x)
    def _u(self,v,l,r,i,x):
        if l==r: self.t[v]=x; return
        m=(l+r)//2
        if i<=m: self._u(2*v,l,m,i,x)
        else: self._u(2*v+1,m+1,r,i,x)
        self.t[v]=self.t[2*v]+self.t[2*v+1]
    def query(self,ql,qr): return self._q(1,0,self.n-1,ql,qr)
    def _q(self,v,l,r,ql,qr):
        if qr<l or r<ql: return 0
        if ql<=l and r<=qr: return self.t[v]
        m=(l+r)//2
        return self._q(2*v,l,m,ql,qr)+self._q(2*v+1,m+1,r,ql,qr)
```
O(log n) per query and update on n elements with 4n storage.

