def tarjan_scc(n, adj):
    idx=[0]; ids=[-1]*n; low=[0]*n; on=[False]*n; stk=[]; sccs=[]
    def strong(v):
        ids[v]=low[v]=idx[0]; idx[0]+=1
        stk.append(v); on[v]=True
        for w in adj[v]:
            if ids[w]==-1: strong(w); low[v]=min(low[v],low[w])
            elif on[w]: low[v]=min(low[v],ids[w])
        if low[v]==ids[v]:
            scc=[]
            while True:
                w=stk.pop(); on[w]=False; scc.append(w)
                if w==v: break
            sccs.append(scc)
    for v in range(n):
        if ids[v]==-1: strong(v)
    return sccs
```
DFS with low-link values. Vertex v starts a new SCC iff low[v]==ids[v]. O(V+E). For large graphs replace recursion with iterative stack.

